source='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value != 3:
                continue
            # The marker anchors a small upright pattern and a full-width base.
            for dc in range(-2, 3):
                if 0 <= r - 2 < h and 0 <= c + dc < w:
                    out[r - 2][c + dc] = 5
            for dr in (-1, 0, 1):
                rr = r + dr
                if 0 <= rr < h:
                    for dc in (-2, 2):
                        if 0 <= c + dc < w:
                            out[rr][c + dc] = 2
            if 0 <= r - 1 < h and 0 <= c < w:
                out[r - 1][c] = 5
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = 3
            rr = r + 2
            if 0 <= rr < h:
                out[rr] = [2] * w
                for cc in range(max(0, c - 2), min(w, c + 3)):
                    out[rr][cc] = 8
    return out
'''
